    let cart = [];
    let activeFilter = "all";

    function renderProducts() {
      const search = document.getElementById("productSearch").value.toLowerCase();
      const visible = products.filter(p =>
        (activeFilter === "all" || p.category === activeFilter) &&
        p.name.toLowerCase().includes(search)
      );

      document.getElementById("productGrid").innerHTML = visible.map(p => `




            ${p.tag}





 4.8 (124)

${p.name}



$${p.price.toFixed(2)} ${p.old ? `$${p.old.toFixed(2)}` : ""}








Company

About
Careers
Press




Support

Help Center
Shipping & Returns
Contact



      `).join("") || `
No products found. Try another search.`;
    }

    function addToCart(id) {
      const item = cart.find(x => x.id === id);
      if (item) item.quantity++;
      else cart.push({ ...products.find(p => p.id === id), quantity: 1 });
      renderCart();
      showToast("Added to your bag.");
    }

    function renderCart() {
      const totalQty = cart.reduce((sum, item) => sum + item.quantity, 0);
      const total = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);
      document.getElementById("cartCount").textContent = totalQty;
      document.getElementById("drawerCount").textContent = totalQty;
      document.getElementById("cartTotal").textContent = `$${total.toFixed(2)}`;

      document.getElementById("cartItems").innerHTML = cart.length ? cart.map(item => `






${item.name}
$${item.price.toFixed(2)}


              −
              ${item.quantity}
              +






©  NexusShop. All rights reserved.




        // --- Sample data (can be replaced by server-side data or API) ---
        const CATEGORIES = [{
                id: 'phones',
                name: 'Smartphones',
                icon: 'fa-mobile-alt'
            },
            {
                id: 'laptops',
                name: 'Laptops',
                icon: 'fa-laptop'
            },
            {
                id: 'clothing',
                name: 'Clothing',
                icon: 'fa-tshirt'
            },
            {
                id: 'gadgets',
                name: 'Gadgets',
                icon: 'fa-headphones'
            },
            {
                id: 'footwear',
                name: 'Footwear',
                icon: 'fa-shoe-prints'
            },
            {
                id: 'accessories',
                name: 'Accessories',
                icon: 'fa-watch'
            }
        ];

        const PRODUCTS = [{
                id: 1,
                title: 'iPhone 14 Pro Max',
                price: 1099,
                oldPrice: 1199,
                rating: 5,
                reviews: 128,
                badge: 'New',
                img: 'https://images.unsplash.com/photo-1601784551446-20c9e07cdbdb?auto=format&fit=crop&w=600&q=80',
                category: 'phones'
            },
            {
                id: 2,
                title: 'MacBook Pro 14"',
                price: 1999,
                rating: 4,
                reviews: 86,
                img: 'https://images.unsplash.com/photo-1593642632823-8f785ba67e45?auto=format&fit=crop&w=600&q=80',
                category: 'laptops'
            },
            {
                id: 3,
                title: 'Apple Watch Series 8',
                price: 349,
                oldPrice: 399,
                rating: 5,
                reviews: 214,
                badge: '-25%',
                img: 'https://images.unsplash.com/photo-1529374255404-311a2a4f1fd9?auto=format&fit=crop&w=600&q=80',
                category: 'accessories'
            },
            {
                id: 4,
                title: 'Nike Air Max 270',
                price: 150,
                rating: 4,
                reviews: 53,
                img: 'https://images.unsplash.com/photo-1542272604-787c3835535d?auto=format&fit=crop&w=600&q=80',
                category: 'footwear'
            },
            {
                id: 5,
                title: 'Sony A7 IV Camera',
                price: 2499,
                rating: 5,
                reviews: 42,
                img: 'https://images.unsplash.com/photo-1526170375885-4d8ecf77b99f?auto=format&fit=crop&w=600&q=80',
                category: 'gadgets'
            },
            {
                id: 6,
                title: 'Chanel No. 5',
                price: 120,
                rating: 5,
                reviews: 189,
                img: 'https://images.unsplash.com/photo-1585386959984-a4155224a1ad?auto=format&fit=crop&w=600&q=80',
                category: 'accessories'
            },
            {
                id: 7,
                title: 'Travel Backpack',
                price: 79,
                oldPrice: 99,
                rating: 4,
                reviews: 67,
                img: 'https://images.unsplash.com/photo-1551232864-3f0890e580d9?auto=format&fit=crop&w=600&q=80',
                category: 'accessories'
            },
            {
                id: 8,
                title: 'Sony WH-1000XM5',
                price: 399,
                rating: 5,
                reviews: 156,
                img: 'https://images.unsplash.com/photo-1600185365483-26d7a4cc7519?auto=format&fit=crop&w=600&q=80',
                category: 'gadgets'
            }
        ];

        // --- Render categories & products ---
        const categoriesGrid = document.getElementById('categoriesGrid');
        const productsGrid = document.getElementById('productsGrid');
        const cartCountEl = document.getElementById('cartCount');
        const searchInput = document.getElementById('searchInput');

        let cartCount = 0;

        function renderCategories() {
            categoriesGrid.innerHTML = '';
            CATEGORIES.forEach(cat => {
                const el = document.createElement('div');
                el.className = 'cat-card';
                el.innerHTML = `



${cat.name}

Explore ${cat.name}
                `;
                el.addEventListener('click', () => {
                    searchInput.value = cat.name;
                    filterProducts(cat.name);
                    window.scrollTo({
                        top: document.getElementById('prod-title').offsetTop - 60,
                        behavior: 'smooth'
                    });
                });
                categoriesGrid.appendChild(el);
            });
        }

        function renderProducts(list) {
            productsGrid.innerHTML = '';
            list.forEach(p => {
                const el = document.createElement('article');
                el.className = 'product';
                el.innerHTML = `
                    ${p.badge ? `
${p.badge}` : ''}




${escapeHtml(p.title)}

${p.category}





$${p.price.toLocaleString()}
                                ${p.oldPrice ? `
${p.oldPrice ? '$'+p.oldPrice.toLocaleString() : ''}` : ''}


${'★'.repeat(Math.round(p.rating))} (${p.reviews})




                         Add


                `;
                productsGrid.appendChild(el);
            });

            // attach listeners to add buttons
            productsGrid.querySelectorAll('.add-btn').forEach(btn => {
                btn.addEventListener('click', (e) => {
                    const id = Number(btn.dataset.id);
                    addToCart(id);
                });
            });
        }

        // --- Utilities ---
        function escapeHtml(text) {
            return String(text).replace(/[&<>"']/g, s => ({
                '&': '&',
                '<': '<',
                '>': '>',
                '"': '"',
                "'": '''
            } [s]));
        }

        function addToCart(productId) {
            const p = PRODUCTS.find(x => x.id === productId);
            if (!p) return;
            cartCount++;
            cartCountEl.textContent = cartCount;
            // Simple feedback
            const btn = document.querySelector(`.add-btn[data-id="${productId}"]`);
            if (btn) {
                const original = btn.innerHTML;
                btn.innerHTML = 'Added ✓';
                btn.disabled = true;
                setTimeout(() => {
                    btn.innerHTML = original;
                    btn.disabled = false;
                }, 1200);
            }
        }

        function updateCartCount() {
            cartCountEl.textContent = cartCount;
        }

        function filterProducts(query) {
            const q = String(query || '').trim().toLowerCase();
            if (!q) {
                renderProducts(PRODUCTS);
                return;
            }
            const filtered = PRODUCTS.filter(p =>
                p.title.toLowerCase().includes(q) ||
                p.category.toLowerCase().includes(q)
            );
            renderProducts(filtered);
        }

        // --- Search handling ---
        document.getElementById('searchBtn').addEventListener('click', () => filterProducts(searchInput.value));
        searchInput.addEventListener('keydown', (e) => {
            if (e.key === 'Enter') filterProducts(e.target.value);
        });

        // --- Mobile menu toggle ---
        const mobileToggle = document.getElementById('mobileToggle');
        const mobileMenu = document.getElementById('mobileMenu');
        mobileToggle.addEventListener('click', () => {
            mobileMenu.style.display = mobileMenu.style.display === 'none' || !mobileMenu.style.display ? 'block' : 'none';
        });

        // --- Simple dropdown (desktop) ---
        const catMenuBtn = document.getElementById('catMenuBtn');
        catMenuBtn && catMenuBtn.addEventListener('click', (e) => {
            e.preventDefault();
            alert('Use the category tiles below to filter — this is a demo.');
        });

        // --- Newsletter subscribe (demo) ---
        document.getElementById('newsletterForm').addEventListener('submit', (e) => {
            e.preventDefault();
            const email = document.getElementById('newsletterEmail').value.trim();
            const msg = document.getElementById('newsletterMsg');
            if (!email || !email.includes('@')) {
                msg.style.display = 'block';
                msg.textContent = 'Please enter a valid email address.';
                msg.style.color = '#ffb3b3';
                return;
            }
            msg.style.display = 'block';
            msg.style.color = '#cce7ff';
            msg.textContent = 'Thanks! You are subscribed.';
            document.getElementById('newsletterEmail').value = '';
            setTimeout(() => msg.style.display = 'none', 3000);
        });

        // --- Countdown timer for deal ---
        (function setupDealTimer() {
            // Target: 1 day from now (demo)
            const now = new Date();
            const target = new Date(now.getTime() + (24 * 60 + 36) * 60 * 1000); // 24h36m
            function tick() {
                const diff = target - new Date();
                const days = Math.floor(diff / (24 * 3600 * 1000));
                const hours = Math.floor((diff % (24 * 3600 * 1000)) / (3600 * 1000));
                const mins = Math.floor((diff % (3600 * 1000)) / (60 * 1000));
                const secs = Math.floor((diff % (60 * 1000)) / 1000);
                document.getElementById('dealDays').textContent = days;
                document.getElementById('dealHours').textContent = String(hours).padStart(2, '0');
                document.getElementById('dealMinutes').textContent = String(mins).padStart(2, '0');
                document.getElementById('dealSeconds').textContent = String(secs).padStart(2, '0');
                if (diff <= 0) clearInterval(timer);
            }
            tick();
            const timer = setInterval(tick, 1000);
        })();

        // --- Small UI bindings ---
        document.getElementById('shopNow').addEventListener('click', () => window.scrollTo({
            top: document.getElementById('prod-title').offsetTop - 60,
            behavior: 'smooth'
        }));
        document.getElementById('exploreDeals').addEventListener('click', () => window.location.hash = '#deals');
        document.getElementById('buyDeal').addEventListener('click', () => {
            cartCount += 1;
            updateCartCount();
            alert('Deal added to cart (demo).');
        });

        // --- Initialization ---
        (function init() {
            renderCategories();
            renderProducts(PRODUCTS);
            updateCartCount();
            document.getElementById('year').textContent = new Date().getFullYear();
        })();

      `).join("") : `
Your bag is waiting for something lovely.`;
    }

    function changeQuantity(id, amount) {
      const item = cart.find(x => x.id === id);
      item.quantity += amount;
      if (item.quantity < 1) removeItem(id);
      else renderCart();
    }

    function removeItem(id) {
      cart = cart.filter(item => item.id !== id);
      renderCart();
      showToast("Item removed from your bag.");
    }

    function toggleCart(force) {
      const drawer = document.getElementById("cartDrawer");
      const isOpen = typeof force === "boolean" ? force : !drawer.classList.contains("show");
      drawer.classList.toggle("show", isOpen);
      document.getElementById("overlay").classList.toggle("show", isOpen);
      document.body.classList.toggle("no-scroll", isOpen);
    }

    function toggleWish(button) {
      button.classList.toggle("active");
      const icon = button.querySelector("i");
      const active = button.classList.contains("active");
      icon.className = active ? "fa-solid fa-heart" : "fa-regular fa-heart";
      showToast(active ? "Saved to your wishlist." : "Removed from your wishlist.");
    }

    function showToast(message) {
      const toast = document.getElementById("toast");
      toast.textContent = message;
      toast.classList.add("show");
      clearTimeout(window.toastTimer);
      window.toastTimer = setTimeout(() => toast.classList.remove("show"), 2600);
    }

    function subscribe(event) {
      event.preventDefault();
      event.target.reset();
      showToast("Welcome to the Nexus list!");
    }

    function checkout() {
      if (!cart.length) return showToast("Your bag is currently empty.");
      showToast("Demo checkout complete — thanks for shopping!");
      cart = [];
      renderCart();
      toggleCart(false);
    }

    function toggleMenu() {
      showToast("Mobile navigation demo — use the links above to explore.");
    }

    document.querySelectorAll(".filter").forEach(button => {
      button.addEventListener("click", () => {
        document.querySelector(".filter.active").classList.remove("active");
        button.classList.add("active");
        activeFilter = button.dataset.filter;
        renderProducts();
      });
    });

    document.getElementById("productSearch").addEventListener("input", renderProducts);

    const saleEnd = Date.now() + 1000 * 60 * 60 * 28;
    function updateCountdown() {
      const remaining = Math.max(0, saleEnd - Date.now());
      const seconds = Math.floor(remaining / 1000);
      const values = [
        ["days", Math.floor(seconds / 86400)],
        ["hours", Math.floor(seconds % 86400 / 3600)],
        ["mins", Math.floor(seconds % 3600 / 60)],
        ["secs", seconds % 60]
      ];
      values.forEach(([id, value]) => document.getElementById(id).childNodes[0].nodeValue = String(value).padStart(2, "0"));
    }

    renderProducts();
    renderCart();
    updateCountdown();
    setInterval(updateCountdown, 1000);
